    /* sidebar layouts: a sidebar of fixed width on wide screens leaves the rest to the tables, which scroll
       sideways inside their own box when still too wide; below 992px the sidebar goes above the results */
    @media (min-width: 992px) {
      .row > .col-sm-4:has(> .well) { flex: 0 0 clamp(280px, 26vw, 360px); width: auto; }
      .row > .col-sm-8[role=main] { flex: 1 1 0; width: auto; min-width: 0; } }
    @media (min-width: 576px) and (max-width: 991.98px) {
      .row > .col-sm-4:has(> .well), .row > .col-sm-8[role=main] { width: 100%%; } }
    .equation { font-family: monospace; font-size: 14px; background: #f4f8f4; border: 1px solid #e5ebe5; padding: 10px 14px; border-radius: 6px; }
    .empty-state { text-align: center; color: #667; background: #fff; border: 1px dashed #d6dfd6; border-radius: 10px; padding: 40px 24px; margin-bottom: 16px; }
    .shiny-html-output.stale-dim { display: block; }   /* uiOutput is display: contents, which opacity does not apply to */
    .is-stale .stale-dim { opacity: .35; filter: grayscale(1); user-select: none; transition: opacity .2s; }
    .flex-none { flex: none; white-space: nowrap; }
    /* Live View plot preview frame */
    .plot-live-wrapper { margin: 12px 0 20px; }
    .plot-live-card {
      max-width: 720px;
      margin: 0 auto;
      background: #ffffff;
      border: 1px solid #dce4dc;
      border-radius: 12px;
      box-shadow: 0 4px 18px rgba(0, 0, 0, .05);
      padding: 14px 18px 18px;
      transition: box-shadow .2s;
    }
    .plot-live-card:hover { box-shadow: 0 6px 24px rgba(0, 0, 0, .08); }
    .plot-live-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 8px;
      margin-bottom: 12px;
      padding-bottom: 8px;
      border-bottom: 1px solid #edf2ed;
    }
    .plot-live-title { font-weight: 600; font-size: 13.5px; color: #202e21; display: inline-flex; align-items: center; }
    .plot-live-viewport {
      width: 100%%;
      display: flex;
      justify-content: center;
      align-items: center;
      min-height: 260px;
      background: #fdfdfd;
      border-radius: 6px;
      overflow: hidden;
    }
    .plot-live-viewport .shiny-plot-output {
      display: flex;
      justify-content: center;
      align-items: center;
      width: auto !important;
      max-width: 100%%;
      height: auto !important;
    }
    .plot-live-viewport img {
      max-width: 100%% !important;
      height: auto !important;
      display: block;
      border-radius: 4px;
    }
    .empty-state i { font-size: 32px; color: %1$s; margin-bottom: 10px; } .empty-state h5 { font-weight: 600; color: #333; }", brand[["main"]], brand[["dark"]], brand[["light"]])

